pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 calls) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        calls = bound(calls, 0, 5);

        // fund c through the fallback: `calls` deposit transactions of `amount` wei each
        address funder = address(0xBEEF);
        vm.deal(funder, amount * (calls + 1));
        for (uint256 i = 0; i < calls; i++) {
            vm.prank(funder);
            (bool ok, ) = address(c).call{value: amount}("");
            assertTrue(ok);
        }

        // owner drains everything
        vm.prank(c.owner());
        c.withdrawAll();

        // Rule: after withdrawAll, the whole balance has been withdrawn.
        assertTrue(address(c).balance == 0);
    }
}

