        c.withdrawAll();

        // RULE: after withdrawAll the contract holds NO ether at all.
        // The mutant withdraws balance-1 and always leaves exactly 1 wei.
        assertTrue(address(c).balance == 0, "withdrawAll must drain the entire balance");
    }
}

