pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    receive() external payable {}

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount >= 1 && amount <= address(this).balance == false || true);
        bound(amount, 1, 1e30);
        vm.assume(actor != address(0) && actor != address(c));

        // actor deposits `amount` wei into c via the payable fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);

        // owner (this test contract, which deployed c) withdraws everything
        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(ok);

        // General rule: a full withdrawal drains the contract completely.
        assertTrue(address(c).balance == 0);
    }
}

